import { ConfigContext, ExpoConfig } from 'expo/config'
import { existsSync } from 'fs'

// Production builds receive Firebase config through project-scoped EAS file variables with
// Sensitive visibility. EAS materialises each uploaded file and exposes its path through the
// matching process.env value. Local and development builds fall back to the gitignored
// root files generated by `npm run setup:firebase`.
const googleServicesJsonPath = process.env.GOOGLE_SERVICES_JSON ?? './google-services.json'
const googleServiceInfoPlistPath =
  process.env.GOOGLE_SERVICE_INFO_PLIST ?? './GoogleService-Info.plist'

if (!process.env.GOOGLE_SERVICES_JSON && !existsSync(googleServicesJsonPath)) {
  console.warn(
    '\n⚠️  google-services.json not found locally and no EAS file env var resolved.\n' +
      '   Run `npm run setup:firebase`, or place the matching Firebase file in the project root.\n'
  )
}
if (!process.env.GOOGLE_SERVICE_INFO_PLIST && !existsSync(googleServiceInfoPlistPath)) {
  console.warn(
    '\n⚠️  GoogleService-Info.plist not found locally and no EAS file env var resolved.\n' +
      '   Run `npm run setup:firebase`, or place the matching Firebase file in the project root.\n'
  )
}

const resolveAppVariant = (): 'development' | 'production' => {
  const variant = process.env.APP_VARIANT

  if (variant === undefined && process.env.NODE_ENV !== 'production') return 'development'
  if (variant === 'development' || variant === 'production') return variant

  throw new Error(
    'APP_VARIANT must be "development" or "production". Configure it in the selected EAS build profile or EAS Update environment.'
  )
}

export default ({ config }: ConfigContext): ExpoConfig => {
  const variant = resolveAppVariant()
  const isProd = variant === 'production'
  const nameSuffix = isProd ? '' : ' (Dev)'

  return {
    ...config,
    name: `${config.name}${nameSuffix}`,
    ios: {
      ...config.ios,
      googleServicesFile: googleServiceInfoPlistPath,
      infoPlist: {
        ...config.ios?.infoPlist,
        ...(variant === 'development' && {
          // For Firebase emulator debugging from real devices (dev only)
          NSAppTransportSecurity: {
            NSAllowsLocalNetworking: true,
            NSAllowsArbitraryLoads: true,
          },
        }),
      },
    },
    android: {
      ...config.android,
      googleServicesFile: googleServicesJsonPath,
    },
  } as ExpoConfig
}
